"""Cluster administration chapters; examples are extracted from the compiled demonstration."""
from build import p, h, ol, ul, table, code, callout, source_link
from client_chapters import example


def dashboard_chapters(ru):
    def text(russian, english):
        return russian if ru else english
    return [
        ("dashboard", text("Dashboard: управление работающим кластером", "Dashboard: administer a running cluster"),
         p(text("RaftClusterDashboard — отдельное ASP.NET Core8 приложение с React, TypeScript, Ant Design6 и Vite. Оно не голосует и не хранит копию прикладных сообщений. Браузер обращается к dashboard, а его backend — к management endpoints нескольких кластеров. Node.js нужен для сборки; опубликованный сервер обслуживает готовый UI сам.",
                "RaftClusterDashboard is a separate ASP.NET Core8 application with React, TypeScript, Ant Design6 and Vite. It never votes or holds a replica of application messages. The browser talks to the dashboard; its backend talks to management endpoints of multiple clusters. Node.js is a build dependency; the published ASP.NET app serves its built UI itself.")) +
         h(text("Запуск локального стенда", "Start the local stand")) + code(
             "./scripts/start-dashboard-stand.ps1 -Voters 3\n# Separate HTTPS + peer mTLS profile:\n./scripts/start-dashboard-stand.ps1 -Voters 5 -Secure -DashboardPort 7440", language="powershell", title="RaftNet8 · PowerShell7") +
         p(text("Пароль первого администратора: не менее12 символов, включая A–Z, a–z, цифру и специальный символ. Скрипт проверяет его до запуска нод и при ошибке предлагает повторный ввод. Для автоматического запуска задайте RAFT_DASHBOARD_BOOTSTRAP_PASSWORD через окружение; неверное значение завершит запуск с объяснением требований.",
                "The first administrator password needs at least12 characters, including A–Z, a–z, a digit and a special character. The script validates it before starting nodes and prompts again on rejection. For unattended runs, supply RAFT_DASHBOARD_BOOTSTRAP_PASSWORD through the environment; an invalid value stops startup with the requirements.")) +
         p(text("Скрипт создаёт новую папку в D:\\Temp\\RaftNet8, запускает отдельный процесс для каждой ноды и ещё два joining процесса, создаёт первого администратора и защищённый профиль подключения. Откройте показанный URL, войдите как admin. Ctrl+C останавливает процессы этого стенда; данные остаются для проверки. Для параллельного стенда задайте другие peer/client/management порты. Пароль не передаётся в командной строке.",
                "The script creates a new directory under D:\\Temp\\RaftNet8, runs an independent process per node plus two joining processes, creates the first administrator and imports a protected connection profile. Open the printed URL and sign in as admin. Ctrl+C stops its owned children and retains their data. Use different peer/client/management ports for simultaneous stands. The password is never a command-line argument.")) +
         ol(*[text(a, b) for a, b in [
             ("Обзор показывает фактического лидера, term, voters/learners, commit/applied, реальную скорость и ресурсы. Пробел или — означает отсутствие измерений; жёлтая плашка предупреждает об устаревших данных.", "Overview shows the observed leader, term, voters/learners, commit/applied, actual rates and resources. A gap or — means unavailable measurements; a warning identifies stale data."),
             ("Ноды: добавьте уже запущенную n4, указав peer6104, client7104 и management7204 при стандартных портах. Существующие процессы сохраняют PID. Удаление лидера сначала передаёт лидерство.", "Nodes: add the already-running n4 using peer6104, client7104 and management7204 with the default port bases. Existing processes keep their PIDs. Removing a leader transfers leadership first."),
             ("Операции: скопируйте operationId. Принятая операция продолжится после закрытия страницы или смены лидера. Отмена Add выполняет журналируемую очистку learner; после начала финального повышения отменять поздно.", "Operations: copy operationId. Accepted work survives closing the browser or changing leaders. Cancelling Add journals learner cleanup; cancellation is too late once final promotion has begun."),
             ("Entities: создайте поток, настройте паузу, размер сообщения и логическую квоту. История остаётся. Просмотр payload доступен только с отдельным разрешением.", "Entities: create a stream and configure pause, message size and logical quota. Existing history remains. Payload preview requires a separate grant."),
             ("Токены и пользователи: выдавайте клиентские права, отзывайте секреты и назначайте доступ к кластерам. Настройки показывают эффективные ограничения хоста; изменение транспорта требует перезапуска.", "Tokens and users: issue/revoke client grants and assign cluster access. Settings show effective host limits; changing transport requires restart.")]]) +
         source_link("docs/CLUSTER-DASHBOARD.md", text("Подробная инструкция и диагностика", "Complete operations and troubleshooting"))),
        ("client-security", text("Токены RaftClient и безопасность администратора", "RaftClient tokens and administrator security"),
         p(text("HTTP и обычный TCP остаются поддерживаемым режимом доверенной сети. По умолчанию dashboard и новый management API слушают loopback. Защищённый профиль требует HTTPS для client/admin API и mTLS между peers; некорректная конфигурация останавливает запуск. Сертификаты, ключи и CA задаёт хост, журнал Raft их не распространяет.",
                "HTTP and plain TCP remain supported for trusted networks. New dashboard/management listeners default to loopback. The secure profile requires HTTPS for client/admin APIs and peer mTLS; invalid configuration stops startup. The host supplies certificates, keys and CA roots; Raft never distributes them.")) +
         h(text("Подключение приложения", "Connect an application")) + example("AdministrationRecipes.cs", "token-provider") +
         p(text("Provider вызывается до discovery и каждого HTTP повтора. Один клиент обслуживает много entities через общий пул соединений. Токен не является ClientId и не заменяет сохранённый cursor подписчика. Храните его в секретном хранилище приложения, а не в URL или логах.",
                "The provider runs before discovery and every HTTP retry. One client serves many entities through a shared connection pool. The token is not a ClientId and does not replace a subscriber's saved cursor. Store it in the application's secret store, never URLs or logs.")) +
         h(text("Выдача ограниченного токена", "Issue a scoped token")) + example("AdministrationRecipes.cs", "issue-token") +
         p(text("Администратор вызывает выдачу с постоянным operationId. Кластер сохраняет ID, SHA256 хеш случайного256-битного секрета, срок и права; исходный секрет возвращается один раз. Повтор после потерянного ответа возвращает прежние метаданные и Secret=null. Такой токен нужно отозвать и заменить. Корневой credential создаётся одноразовым локальным BootstrapAsync с секретом хоста и по умолчанию действует30 дней. Обязательно ротируйте его до истечения и сохраняйте другой доступ администратора.",
                "Issue a token using a stable operationId. The cluster stores its ID, SHA256 hash of a random256-bit secret, expiry and permissions; the secret is returned once. A retry after a lost response returns the same metadata with Secret=null. Revoke and replace that unusable token. BootstrapAsync creates the first root credential locally using a host secret; its default expiry is30 days. Rotate it before expiry and preserve another administrative access path.")) +
         table([text("Право", "Permission"), text("Назначение", "Purpose")], [
             ["Discover", text("Маршруты и лидер; допустимо для entity-scoped токена", "Routes and leader; allowed for an entity-scoped token")],
             ["Publish / CreateEntity", text("Публикация / создание разрешённых entities", "Publish / create explicitly permitted entities")],
             ["ReadMetadata / ReadPayload", text("Номера, размеры / содержимое", "IDs and lengths / message content")],
             ["Observe", text("Диагностика всей группы при scope *", "Group diagnostics with scope *")],
             ["ManageEntities / ManageNodes / ManageTokens", text("Политики / состав / credentials", "Policies / membership / credentials")]]) +
         p(text("Права проверяются до чтения тела, после ReadIndex для чтений и при применении записей. Отзыв, расположенный в журнале раньше команды, блокирует её; ранее упорядоченная команда может завершиться. Время допуска фиксируется лидером для детерминированного replay; синхронизируйте часы хостов. Результат timeout остаётся неопределённым. Повтор публикации использует тот же requestId, данные и credential; его timestamp может измениться.",
                "Permissions are checked before request bodies, after ReadIndex for reads and at log application for writes. A revocation ordered before a command blocks it; an earlier ordered command may finish. Admission time is recorded by the leader for deterministic replay, so synchronize host clocks. A timeout remains uncertain. Retrying a publication uses the same requestId, data and credential; its admission timestamp may change.")) +
         h(text("Аккаунты браузера", "Browser accounts")) +
         p(text("У dashboard собственные ASP.NET Identity аккаунты: Viewer читает назначенные кластеры, Operator управляет составом/entities, Admin управляет аккаунтами и токенами. Даже Admin требует CanReadPayload для preview. Первый аккаунт создаётся bootstrap-admin при остановленном dashboard. Защищённый профиль требует TOTP для Admin/Operator; сохраните одноразовые recovery codes. Cookie HttpOnly/SameSite и CSRF защищают браузерную сессию, блокировка и rate limit ограничивают перебор. Для чувствительных действий требуется вход за последние5 минут.",
                "Dashboard accounts use ASP.NET Identity: Viewer reads assigned clusters, Operator manages membership/entities, Admin manages accounts and tokens. Even Admin needs CanReadPayload for preview. Create the first account with bootstrap-admin while the dashboard is stopped. Secure mode requires TOTP for Admin/Operator; preserve single-use recovery codes. HttpOnly/SameSite cookies and CSRF protect the browser session; lockout and rate limits restrict guessing. Sensitive actions require authentication within5 minutes.")) +
         callout(text("Без кворума", "Without quorum"), text("Только специально доверенный mTLS сертификат dashboard может читать локальные ресурсы и состояние ноды без ReadIndex. Он не даёт payload, управление или токены. Без него видны только последние сохранённые показатели. Потеря последнего административного секрета не открывает обход кворума.",
             "Only a specially trusted dashboard mTLS certificate may read node-local resources/status without ReadIndex. It grants neither payload nor mutations/token issuance. Without it only cached observations remain. Losing the last administrative secret never enables a quorum bypass."))),
        ("entity-administration", text("Политики entities и долговечные операции", "Entity policies and durable operations"),
         example("AdministrationRecipes.cs", "entity-policy") +
         p(text("Настройка и публикации применяются в одном порядке Raft. Проверка квоты и увеличение messageId находятся в одной транзакции, поэтому конкурентные клиенты не могут превысить лимит. Standard считает все сохранённые payload-байты; HighSpeedCache — последнее значение. Уменьшение квоты не удаляет данные. Приостановка запрещает новые публикации, но разрешает чтение. Режим entity неизменяем; удаления, сброса счётчика и отдельного memory-only потока здесь нет.",
                "Policies and publications share Raft order. Quota validation and messageId advancement are atomic, so concurrent clients cannot overshoot. Standard counts all retained payload bytes; HighSpeedCache counts the latest value. Lowering a quota never deletes data. Pausing blocks new publications while reads continue. Entity mode is immutable; this version has no deletion, counter reset or memory-only stream.")) +
         example("AdministrationRecipes.cs", "admin-add") +
         p(text("Административный SDK работает через отдельные management endpoints. Add/Remove, snapshot и transfer имеют долговечное намерение и наблюдаемый результат. Только одна управляющая операция занимает общую очередь. Библиотека не запускает процесс новой ноды: сначала оператор запускает JoiningNode с исходным bootstrap-составом, затем Add проверяет возможности и включает learner. Бизнес-записи продолжаются при его догонянии. Смена лидера продолжает подтверждённое намерение.",
                "The admin SDK uses separate management endpoints. Add/Remove, snapshot and transfer have durable intentions and observable results. One control operation occupies the shared lane at a time. The library never starts the new process: an operator first starts JoiningNode with the original bootstrap membership, then Add verifies capabilities and introduces a learner. Business publications continue during catch-up. A new leader resumes the committed intention."))),
        ("dashboard-storage", text("Что хранится, пределы и переход на cluster-v2", "Storage, limits and upgrading to cluster-v2"),
         table([text("Место", "Location"), text("Содержимое", "Contents")], [
             ["node/log", text("Технический журнал, hard state, peer directory и результаты core membership", "Technical log, hard state, peer directory and core membership results")],
             ["node/messages", text("История/последние значения, счётчики, политики, token hashes, admin intentions и аудит; один checkpoint", "History/latest values, counters, policies, token hashes, admin intentions and audit; one checkpoint")],
             ["node/images", text("Согласованный образ приложения и служебного состояния на одной границе", "Consistent application/service images at one log boundary")],
             ["dashboard/database + keys", text("Отдельная DBreeze: аккаунты, защищённые credentials/MFA, профили, минутные графики и локальный аудит", "Separate DBreeze: accounts, protected credentials/MFA, profiles, minute charts and local audit")],
             ["RAM", text("Ограниченные кэши и10 минут подробных точек; не единственное место хранения сообщений", "Bounded caches and10 minutes of detailed points; never the only retained message copy")]]) +
         p(text("Секрет токена не попадает в журнал, кластерную БД или snapshot. Сертификаты/ключи находятся в конфигурации хоста. На Windows ключи Data Protection защищены DPAPI конкретной учётной записи; на других ОС защитите каталог и key ring средствами хоста. Резервируйте dashboard database вместе с keys. Они не реплицируются кластером.",
                "Bearer secrets never enter the cluster log/database or snapshot. Certificates/keys belong to host configuration. On Windows Data Protection keys use that OS account's DPAPI; on other platforms protect the key ring/directory through host controls. Back up dashboard database together with keys. Raft does not replicate them.")) +
         table([text("Лимит по умолчанию", "Default limit"), text("Значение", "Value")], [
             [text("Съём метрик / обход файлов", "Resource sample / file scan"), "1s /30s;100000 files"],
             [text("Детальные / минутные графики", "Detailed / minute history"), "600 points/profile;7 days;400000 rows total"],
             [text("Dashboard профили / ноды / SSE", "Dashboard profiles / nodes / SSE"), "32 /128 per profile /64; notification queue1"],
             [text("Параллельный опрос", "Concurrent polling"), "4 clusters /8 diagnostics"],
             [text("Сбор одновременных management reads", "Concurrent management read collection"), "2ms;1 running +1 waiting batch; no read lease"],
             [text("Management запросы / diagnostics", "Management requests / diagnostics"), "16 /8;64KiB body;16KiB headers"],
             [text("Payload preview", "Payload preview"), "4096B; explicit permission"],
             [text("Аккаунты / локальный аудит", "Accounts / local audit"), "1024 /10000 rows"]]) +
         p(text("Скорость считается по одному лидеру, а не сумме реплик. p99 берётся из совместимых гистограмм, а не усреднения p99; это верхняя граница bucket. End-to-end клиентская задержка измеряется отдельно. RSS процесса отличается от RAM хоста; логические байты entity отличаются от файлов DBreeze, журнала и снимков. Нельзя суммировать один и тот же хост/том по количеству нод. Неизвестные значения показываются явно.",
                "Rates use one leader, never a replica sum. p99 comes from compatible histograms rather than averaging p99 values; it is a bucket upper bound. Client end-to-end latency is measured separately. Process RSS differs from host RAM; logical entity bytes differ from DBreeze/log/image files. Never multiply a shared host/volume by its node count. Unknown measurements are explicit.")) +
         p(text("Одновременные management-наблюдения собираются перед запуском свежего ReadIndex. Запрос, пришедший после начала барьера, ждёт следующий; готовый результат не используется как lease. Права повторно проверяются после ожидания. BatchObservationReads=false отключает сбор для диагностики. Таймеры предложений Raft, подтверждение записи и частота метрик остаются прежними. Справочник management-адресов читается из ограниченного неизменяемого RAM-представления, обновляемого после commit/restore.",
                "Concurrent management observations collect before a fresh ReadIndex starts. A request arriving after that start waits for the next read; a completed result is never reused as a lease. Authorization is checked again after waiting. BatchObservationReads=false disables collection for diagnostics. Raft proposal timers, write acknowledgment and metric frequency stay unchanged. Management routes use a bounded immutable RAM view refreshed after commit/restore.")) +
         callout(text("Рост диска", "Disk growth"), text("Standard история, durable request results, токены и кластерный аудит не имеют TTL. HighSpeedCache удаляет прежний прикладной payload, но не всю историю технического журнала и idempotency. Планируйте место для snapshot/replay/install копий; пауза или квота не освобождает уже занятое место.",
             "Standard history, durable request results, tokens and cluster audit have no TTL. HighSpeedCache removes prior application payloads, not all technical-log/idempotency history. Budget snapshot/replay/install copies; a pause or quota does not release already-occupied space."), "warning") +
         p(text("TLS защищает соединения. Payload, технический журнал и снимки эта версия не шифрует на диске: при необходимости используйте шифрование тома/резервных копий либо собственный зашифрованный payload. Секреты bearer-токенов в реплицируемое состояние не попадают. Credentials и MFA-ключи dashboard защищены Data Protection, пароли — хешами Identity; для восстановления сохраняйте и базу dashboard, и её key ring.",
                "TLS protects connections. This version does not encrypt payloads, technical logs or snapshots at rest: use volume/backup encryption or application-encrypted payloads when needed. Bearer secrets never enter replicated state. Dashboard credentials and MFA keys use Data Protection, passwords use Identity hashes; recovery requires both the dashboard database and its key ring.")) +
         h(text("Offline copy upgrade", "Offline copy upgrade")) +
         p(text("Core wire3/raft8-v4 сохранён. Прикладной формат теперь cluster-v2; peers обмениваются его version preamble вне core frames и отклоняют старое приложение. Остановите всю группу и конвертируйте каждый node root в новую папку. Не смешивайте бинарные версии. Исходник сохраняется; проверяются хеши файлов, сообщения, счётчики, checkpoints и completed snapshots. Живой движок, незавершённый install, нестандартный images path и существующая destination отклоняются.",
                "Core wire3/raft8-v4 remains unchanged. The application is now cluster-v2; peers exchange its version preamble outside core frames and reject old applications. Stop the whole group and convert each node root into a new directory. Never mix binaries. Source files remain intact; file hashes, messages, counters, checkpoints and completed snapshots are checked. A live engine, pending install, nonstandard image path or existing destination is rejected.")) + code(
             "dotnet run --project HumanTest/Raft.Cluster.Demo -c Release -- migrate-cluster-v2 `\n  --source D:/OldCluster/n1 --destination D:/NewCluster/n1 `\n  --options D:/OldCluster/n1/node-options.json", language="powershell", title="RaftNet8") +
         source_link("docs/CLUSTER-DASHBOARD.md", text("Полная процедура, ограничения и команды проверки", "Full procedure, limits and verification commands")))
    ]
